                    if any(k in f.lower() for k in ['cymatics', 'muse', 'vst']):
                        vst3_files.append((f, os.path.join(root, f)))

print(f'Total VST3 / Audio Plugins Found across search roots: {len(vst3_files)}')
for name, p in vst3_files:
    print(f'  -> {name} | {p}')
